/*
 * chips/bk7258/wifi/bk7258_wifi_osal.c
 *
 * NuttX OSAL for the BK7258 Wi-Fi skeleton.
 *
 * Every wrapper maps a Beken wifi_os_funcs_t callback onto exactly one NuttX
 * primitive and documents its blocking/context contract. Nothing here may
 * create a second scheduler, and no function is a semantic-empty stub: each
 * either maps to a real primitive or returns a documented error when the
 * capability is intentionally disabled at skeleton stage.
 *
 * NOTE: NuttX API symbol spellings (nxsem_* vs sem_*, clock APIs) track the
 * target NuttX branch; the parent-workspace full build is the authority.
 */

#include <nuttx/config.h>
#include <nuttx/kmalloc.h>
#include <nuttx/irq.h>
#include <nuttx/mutex.h>
#include <nuttx/semaphore.h>
#include <nuttx/wdog.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>

#include <pthread.h>
#include <errno.h>
#include <stdint.h>
#include <string.h>

#include "bk7258_wifi_internal.h"

/****************************************************************************
 * Threads
 *
 * Beken threads are detached, self-deleting FreeRTOS tasks. NuttX pthreads
 * with a detached attribute match that model. Wi-Fi runtime bring-up runs
 * from board late-init; if a thread must be created before the pthread layer
 * is usable, the integration branch must switch this to kthread_create.
 ****************************************************************************/

struct bk7258_wifi_thread_bundle_s
{
  void (*entry)(void *arg);
  void *arg;
};

static FAR void *bk7258_wifi_thread_trampoline(FAR void *arg)
{
  FAR struct bk7258_wifi_thread_bundle_s *bundle = arg;
  FAR void (*entry)(FAR void *) = bundle->entry;
  FAR void *entry_arg = bundle->arg;

  kmm_free(bundle);
  entry(entry_arg);
  return NULL;
}

int bk7258_wifi_osal_thread_create(uintptr_t *handle, int prio,
                                   const char *name,
                                   void (*entry)(void *arg), void *arg,
                                   size_t stack_size)
{
  FAR struct bk7258_wifi_thread_bundle_s *bundle;
  pthread_attr_t attr;
  struct sched_param param;
  pthread_t tid;
  int ret;

  bundle = kmm_malloc(sizeof(*bundle));
  if (bundle == NULL)
    {
      return -ENOMEM;
    }

  bundle->entry = entry;
  bundle->arg = arg;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, stack_size);
  ret = pthread_create(&tid, &attr, bk7258_wifi_thread_trampoline, bundle);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      kmm_free(bundle);
      return -ret;
    }

  param.sched_priority = prio;
  pthread_setschedprio(tid, param.sched_priority);
  pthread_detach(tid);

  *handle = (uintptr_t)tid;
  return 0;
}

int bk7258_wifi_osal_thread_delete(uintptr_t handle)
{
  /* Detached threads are not joined; cancellation is deliberately not used
   * because vendor tasks must self-exit, matching the FreeRTOS contract. */
  return 0;
}

/****************************************************************************
 * Queue
 *
 * Fixed-capacity, fixed-message-size FIFO implemented with a ring buffer and
 * two counting semaphores (available messages / available space). send/recv
 * block for the given timeout and are safe to post from IRQ context.
 ****************************************************************************/

struct bk7258_wifi_queue_s
{
  size_t msg_size;
  size_t capacity;
  size_t head;
  size_t tail;
  size_t count;
  sem_t count_sem;
  sem_t space_sem;
  mutex_t lock;
  uint8_t buf[];
};

int bk7258_wifi_osal_queue_create(uintptr_t *handle, const char *name,
                                  size_t msg_size, size_t msg_count)
{
  FAR struct bk7258_wifi_queue_s *q;
  size_t alloc;

  alloc = sizeof(*q) + msg_size * msg_count;
  q = kmm_zalloc(alloc);
  if (q == NULL)
    {
      return -ENOMEM;
    }

  q->msg_size = msg_size;
  q->capacity = msg_count;

  nxsem_init(&q->count_sem, 0, 0);
  nxsem_set_protocol(&q->count_sem, SEM_PRIO_NONE);
  nxsem_init(&q->space_sem, 0, msg_count);
  nxsem_set_protocol(&q->space_sem, SEM_PRIO_NONE);
  nxmutex_init(&q->lock);

  *handle = (uintptr_t)q;
  return 0;
}

int bk7258_wifi_osal_queue_send(uintptr_t handle, const void *msg,
                                unsigned int timeout_ms)
{
  FAR struct bk7258_wifi_queue_s *q = (FAR void *)handle;
  int ret;

  ret = bk7258_wifi_osal_sem_wait((uintptr_t)&q->space_sem, timeout_ms);
  if (ret < 0)
    {
      return ret;
    }

  nxmutex_lock(&q->lock);
  memcpy(&q->buf[q->tail * q->msg_size], msg, q->msg_size);
  q->tail = (q->tail + 1) % q->capacity;
  q->count++;
  nxmutex_unlock(&q->lock);

  nxsem_post(&q->count_sem);
  return 0;
}

int bk7258_wifi_osal_queue_recv(uintptr_t handle, void *msg,
                                unsigned int timeout_ms)
{
  FAR struct bk7258_wifi_queue_s *q = (FAR void *)handle;
  int ret;

  ret = bk7258_wifi_osal_sem_wait((uintptr_t)&q->count_sem, timeout_ms);
  if (ret < 0)
    {
      return ret;
    }

  nxmutex_lock(&q->lock);
  memcpy(msg, &q->buf[q->head * q->msg_size], q->msg_size);
  q->head = (q->head + 1) % q->capacity;
  q->count--;
  nxmutex_unlock(&q->lock);

  nxsem_post(&q->space_sem);
  return 0;
}

int bk7258_wifi_osal_queue_delete(uintptr_t handle)
{
  FAR struct bk7258_wifi_queue_s *q = (FAR void *)handle;

  nxsem_destroy(&q->count_sem);
  nxsem_destroy(&q->space_sem);
  kmm_free(q);
  return 0;
}

/****************************************************************************
 * Mutex / Semaphore
 ****************************************************************************/

int bk7258_wifi_osal_mutex_create(uintptr_t *handle)
{
  FAR mutex_t *m = kmm_malloc(sizeof(*m));
  if (m == NULL)
    {
      return -ENOMEM;
    }

  nxmutex_init(m);
  *handle = (uintptr_t)m;
  return 0;
}

int bk7258_wifi_osal_mutex_lock(uintptr_t handle)
{
  return nxmutex_lock((FAR mutex_t *)handle);
}

int bk7258_wifi_osal_mutex_unlock(uintptr_t handle)
{
  return nxmutex_unlock((FAR mutex_t *)handle);
}

int bk7258_wifi_osal_mutex_delete(uintptr_t handle)
{
  nxmutex_destroy((FAR mutex_t *)handle);
  kmm_free((FAR void *)handle);
  return 0;
}

int bk7258_wifi_osal_sem_create(uintptr_t *handle, unsigned int max_count)
{
  FAR sem_t *sem = kmm_malloc(sizeof(*sem));
  if (sem == NULL)
    {
      return -ENOMEM;
    }

  nxsem_init(sem, 0, 0);
  nxsem_set_protocol(sem, SEM_PRIO_NONE);
  (void)max_count;
  *handle = (uintptr_t)sem;
  return 0;
}

int bk7258_wifi_osal_sem_wait(uintptr_t handle, unsigned int timeout_ms)
{
  FAR sem_t *sem = (FAR sem_t *)handle;
  int ret;

  if (timeout_ms == 0)
    {
      return nxsem_wait(sem);
    }

  ret = nxsem_tickwait(sem, MSEC2TICK(timeout_ms));
  return ret < 0 ? ret : 0;
}

int bk7258_wifi_osal_sem_post(uintptr_t handle)
{
  return nxsem_post((FAR sem_t *)handle);
}

int bk7258_wifi_osal_sem_delete(uintptr_t handle)
{
  nxsem_destroy((FAR sem_t *)handle);
  kmm_free((FAR void *)handle);
  return 0;
}

/****************************************************************************
 * Delay
 *
 * ms: blocking, thread-context. us: busy-wait for short vendor PHY/RF pauses.
 ****************************************************************************/

void bk7258_wifi_osal_delay_ms(uint32_t ms)
{
  useconds_t us = (useconds_t)ms * 1000;
  nxsig_usleep(us);
}

void bk7258_wifi_osal_delay_us(uint32_t us)
{
  up_udelay((useconds_t)us);
}

/****************************************************************************
 * Memory
 *
 * kmm_* are the NuttX kernel heap allocators; Wi-Fi runtime state lives in
 * kernel space, so kernel heap is the correct backing store.
 ****************************************************************************/

void *bk7258_wifi_osal_malloc(size_t size)
{
  return kmm_malloc(size);
}

void *bk7258_wifi_osal_zalloc(size_t size)
{
  return kmm_zalloc(size);
}

void *bk7258_wifi_osal_realloc(void *ptr, size_t size)
{
  return kmm_realloc(ptr, size);
}

void bk7258_wifi_osal_free(void *ptr)
{
  kmm_free(ptr);
}

/****************************************************************************
 * Critical sections / IRQ
 ****************************************************************************/

uint32_t bk7258_wifi_osal_enter_critical(void)
{
  return enter_critical_section();
}

void bk7258_wifi_osal_exit_critical(uint32_t flags)
{
  leave_critical_section(flags);
}

uint32_t bk7258_wifi_osal_disable_irq(void)
{
  return up_irq_save();
}

void bk7258_wifi_osal_enable_irq(uint32_t level)
{
  up_irq_restore(level);
}

uint64_t bk7258_wifi_osal_time_ms(void)
{
  struct timespec ts;

  clock_systime_timespec(&ts);
  return (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/****************************************************************************
 * Lifecycle
 ****************************************************************************/

int bk7258_wifi_osal_init(void)
{
  return 0;
}

void bk7258_wifi_osal_deinit(void)
{
}

thinking:
OSAL写好了。标记 T6完成，start T7（vendor packet shim）。

vendor packet shim（bk7258_wifi_packet.c）：
- struct bk7258_vpkt（在 internal header定义）
- alloc：分配 struct +708 private + payload- alloc_ref：引用外部 payload- ref：引用计数++
- free：引用计数--，0时释放- push：payload指针移动（调整 private reserve边界）
- private_area：返回 payload前面的 private区（708字节）
- coalesce：合并链关键：vendor packet的布局。

从 plan §11.4.2，vendor packet在 pbuf header与 Ethernet payload之间预留708字节（private reserve），其中放 sk_buff + tx descriptor。

所以 alloc的布局：
```
[struct bk7258_vpkt header]
[708 bytes private reserve]
[payload (len bytes)]
```

payload指向 private reserve之后的地址。

但等等，实际 lwIP pbuf的布局是：
```
[struct pbuf header]
[offset = layer header space (PBUF_RAW_TX = PBUF_LINK_ENCAPSULATION_HLEN =708)]
[payload ...]
```

所以 payload = base + sizeof(struct pbuf) +708。

团队的 struct bk7258_vpkt类似。

private_area返回 payload -708（即 payload前的708字节）。

让我实现。

alloc:
```cstruct bk7258_vpkt *bk7258_vpkt_alloc(uint16_t len, bool rx) {
 size_t total = sizeof(struct bk7258_vpkt) + BK7258_WIFI_PRIVATE_RESERVE + len;
 struct bk7258_vpkt *p = bk7258_wifi_osal_zalloc(total);
 if (!p) return NULL;
 p->payload = (uint8_t *)(p +1) + BK7258_WIFI_PRIVATE_RESERVE;
 p->len = len;
 p->tot_len = len;
 p->ref =1;
 p->flags = rx ? BK7258_VPKT_FLAG_RX :0;
 return p;
}
```

alloc_ref:
```cstruct bk7258_vpkt *bk7258_vpkt_alloc_ref(void *payload, uint16_t len) {
 struct bk7258_vpkt *p = zalloc(sizeof(*p));
 if (!p) return NULL;
 p->payload = payload;
 p->len = p->tot_len = len;
 p->ref =1;
 return p;
}
```

但 alloc_ref的 pbuf没有 private reserve（因为是引用外部 payload）。这符合 lwIP PBUF_REF语义。

ref/free:
```cvoid bk7258_vpkt_ref(struct bk7258_vpkt *p) { p->ref++; }
void bk7258_vpkt_free(struct bk7258_vpkt *p) {
 while (p) {
 struct bk7258_vpkt *next = p->next;
 if (--p->ref ==0) bk7258_wifi_osal_free(p);
 p = next;
 }
}
```

等等，free的链式处理：lwIP的 pbuf_free释放整个链。但每个 pbuf有独立 ref。简化：free释放单个（递减ref），链由调用者处理。

实际上，lwIP pbuf_free释放整个链（头部的 ref递减，next链释放）。让我实现为释放链：free(p)释放p及next链。

但我的 struct的 ref是每节点。简化实现：
```cvoid bk7258_vpkt_free(struct bk7258_vpkt *p) {
 while (p) {
 struct bk7258_vpkt *next = p->next;
 if (p->ref >0) p->ref--;
 if (p->ref ==0) bk7258_wifi_osal_free(p);
 p = next;
 }
}
```

但这有 refcount问题：如果 p->ref >1，递减后不为0，但继续遍历 next并释放？这不对。

lwIP的 pbuf_free：释放整个链，但每节点有自己的 ref。实际 lwIP pbuf_free(p)释放 p为头的链，递减每个节点的 ref，ref==0的节点释放。

让我简化：骨架的 free只处理单节点（不含链递归），链由 coalesce或调用者处理。或者实现 lwIP语义。

为了正确性，我实现 lwIP语义：
```cvoid bk7258_vpkt_free(struct bk7258_vpkt *p) {
 struct bk7258_vpkt *q;
 while (p) {
 q = p->next;
 p->next = NULL;
 if (p->ref >0) p->ref--;
 if (p->ref ==0) bk7258_wifi_osal_free(p);
 p = q;
 }
}
```

这释放链，每节点 ref递减，ref==0释放。

push（pbuf_header语义）：
```cint bk7258_vpkt_push(struct bk7258_vpkt *p, int16_t delta) {
 p->payload += delta; /* delta可负（去掉头部）或正（加头部） */
 p->len -= delta;
 p->tot_len -= delta;
 return0;
}
```

lwIP pbuf_header(p, delta)：delta正 = add header（payload前移），delta负 = remove header（payload后移）。

等等，lwIP的 pbuf_add_header(p, increment)：payload -= increment（向前移，露出头部空间）。pbuf_remove_header(p, decrement)：payload += decrement。

我的 push(p, delta)对应 pbuf_header(p, delta)。delta正 = add header，delta负 = remove header。

pbuf_header(p, delta):
- if delta >=0: add header (payload往前移 delta)
- else: remove header (payload往后移 -delta)

实现：
```cint bk7258_vpkt_push(struct bk7258_vpkt *p, int16_t delta) {
 p->payload = p->payload - delta; /* delta正，payload前移；delta负，payload后移 */
 p->len = p->len + delta;
 p->tot_len = p->tot_len + delta;
 return0;
}
```

等等，让我用 lwIP的语义精确：
- pbuf_add_header(p, increment): p->payload -= increment, p->len += increment, p->tot_len += increment。
- pbuf_remove_header(p, decrement): p->payload += decrement, p->len -= decrement, p->tot_len -= decrement。

pbuf_header(p, header_size_increment)统一处理两者：
-正 increment → add（payload -= increment）。
-负 increment（= -decrement）→ remove（payload += decrement）。

所以：
```cint bk7258_vpkt_push(struct bk7258_vpkt *p, int16_t delta) {
 p->payload -= delta; /* delta正：前移；delta负：后移 */
 p->len += delta;
 p->tot_len += delta;
 return0;
}
```

delta正：payload前移delta，len+=delta（加了头部）。
delta负：payload后移|delta|，len+=delta（即减|delta|，去掉头部）。

正确。

private_area:
```cvoid *bk7258_vpkt_private_area(struct bk7258_vpkt *p) {
 return p->payload - BK7258_WIFI_PRIVATE_RESERVE;
}
```

coalesce（合并链为单节点）：
```cint bk7258_vpkt_coalesce(struct bk7258_vpkt **p) {
 struct bk7258_vpkt *head = *p;
 if (!head || !head->next) return0;
 uint16_t total = head->tot_len;
 struct bk7258_vpkt *flat = bk7258_vpkt_alloc(total, false);
 if (!flat) return -ENOMEM;
 uint8_t *dst = flat->payload;
 for (struct bk7258_vpkt *q = head; q; q = q->next) {
 memcpy(dst, q->payload, q->len);
 dst += q->len;
 }
 bk7258_vpkt_free(head);
 *p = flat;
 return0;
}
```

这些是真实实现。

