struct bk7258_wifi_sem_s
{
  sem_t sem;
  unsigned int max_count;
  volatile unsigned int count;
};

int bk7258_wifi_osal_sem_create(uintptr_t *handle, unsigned int max_count)
{
  FAR struct bk7258_wifi_sem_s *s = kmm_zalloc(sizeof(*s));
  if (s == NULL)
    {
      return -ENOMEM;
    }

  nxsem_init(&s->sem, 0, 0);
  nxsem_set_protocol(&s->sem, SEM_PRIO_NONE);
  s->max_count = max_count;
  *handle = (uintptr_t)s;
  return 0;
}

int bk7258_wifi_osal_sem_wait(uintptr_t handle, unsigned int timeout_ms)
{
  FAR struct bk7258_wifi_sem_s *s = (FAR void *)handle;
  uint32_t flags;
  int ret;

  /* 0 = non-blocking poll (Beken NO_WAIT). UINT32_MAX = block forever
   * (Beken BEKEN_WAIT_FOREVER). Note this is the inverse of nxsem_wait's
   * plain "block indefinitely" meaning, so it must not call nxsem_wait for
   * timeout 0. */
  if (timeout_ms == 0)
    {
      ret = nxsem_trywait(&s->sem);
    }
  else if (timeout_ms == UINT32_MAX)
    {
      ret = nxsem_wait(&s->sem);
    }
  else
    {
      ret = nxsem_tickwait(&s->sem, MSEC2TICK(timeout_ms));
    }

  if (ret >= 0)
    {
      flags = enter_critical_section();
      s->count--;
      leave_critical_section(flags);
    }

  return ret;
}

int bk7258_wifi_osal_sem_post(uintptr_t handle)
{
  FAR struct bk7258_wifi_sem_s *s = (FAR void *)handle;
  uint32_t flags;

  if (s->max_count != 0)
    {
      flags = enter_critical_section();
      if (s->count >= s->max_count)
        {
          leave_critical_section(flags);
          return -EAGAIN;
        }

      s->count++;
      leave_critical_section(flags);
    }

  return nxsem_post(&s->sem);
}

int bk7258_wifi_osal_sem_delete(uintptr_t handle)
{
  FAR struct bk7258_wifi_sem_s *s = (FAR void *)handle;

  nxsem_destroy(&s->sem);
  kmm_free(s);
  return 0;
}

/****************************************************************************
 * Timer
 *
 * Beken software timers fire a callback in task context. NuttX wdog callbacks
 * run in IRQ context, so a wdog expiry is deferred through the low-priority
 * work queue to preserve the vendor callback context contract.
 ****************************************************************************/

struct bk7258_wifi_timer_s
{
  struct wdog_s wdog;
  struct work_s work;
  void (*cb)(void *arg);
  void *arg;
  uint32_t period_ms;
  bool periodic;
  bool running;
};

static void bk7258_wifi_osal_timer_work(FAR void *arg)
{
  FAR struct bk7258_wifi_timer_s *t = arg;

  t->cb(t->arg);
  if (t->periodic && t->running)
    {
      wd_start(&t->wdog, MSEC2TICK(t->period_ms),
               bk7258_wifi_osal_timer_work, (wdparm_t)t);
    }
  else
    {
      t->running = false;
    }
}

uintptr_t bk7258_wifi_osal_timer_create(uint32_t period_ms, bool periodic,
                                        void (*cb)(void *arg), void *arg)
{
  FAR struct bk7258_wifi_timer_s *t = kmm_zalloc(sizeof(*t));
  if (t == NULL)
    {
      return 0;
    }

  t->cb = cb;
  t->arg = arg;
  t->period_ms = period_ms;
  t->periodic = periodic;
  return (uintptr_t)t;
}

int bk7258_wifi_osal_timer_start(uintptr_t handle)
{
  FAR struct bk7258_wifi_timer_s *t = (FAR void *)handle;

  if (t->running)
    {
      return 0;
    }

  t->running = true;
  wd_start(&t->wdog, MSEC2TICK(t->period_ms),
           bk7258_wifi_osal_timer_work, (wdparm_t)t);
  return 0;
}

int bk7258_wifi_osal_timer_stop(uintptr_t handle)
{
  FAR struct bk7258_wifi_timer_s *t = (FAR void *)handle;

  wd_cancel(&t->wdog);
  t->running = false;
  return 0;
}

int bk7258_wifi_osal_timer_delete(uintptr_t handle)
{
  FAR struct bk7258_wifi_timer_s *t = (FAR void *)handle;

  wd_cancel(&t->wdog);
  kmm_free(t);
  return 0;
}

bool bk7258_wifi_osal_timer_is_running(uintptr_t handle)
{
  FAR struct bk7258_wifi_timer_s *t = (FAR void *)handle;

  return t->running;
}

