/*
 * chips/bk7258/wifi/glue/include/os/os.h
 *
 * NuttX reimplementation of the Armino rtos_* interface. Declares the
 * callbacks the vendored glue and libwifi.a depend on; implementations live
 * in rtos_shim.c (thread/queue/mutex/sem/timer/irq/time) and os_shim.c
 * (memory). No second scheduler: scheduler/priority APIs map onto the already
 * running NuttX scheduler.
 */

#ifndef __BK7258_WIFI_GLUE_OS_OS_H
#define __BK7258_WIFI_GLUE_OS_OS_H

