#define GLOBAL_INT_DISABLE()           do { irq_level = rtos_enter_critical(); } while (0)
#define GLOBAL_INT_RESTORE()           do { rtos_exit_critical(irq_level); } while (0)

typedef void           *beken_thread_arg_t;
