 * chips/bk7258/wifi/glue/rtos_shim.c
 *
 * NuttX implementation of the Armino rtos_* callbacks (thread/queue/mutex/
 * semaphore/timer/irq/time/event/heap). Maps each callback onto one NuttX
 * primitive; no second scheduler. Unsupported-at-skeleton capabilities return
 * a documented error rather than a silent no-op.
 */

