/****************************************************************************
 * Threads
 ****************************************************************************/

struct bk7258_rtos_thread_s
{
  beken_thread_function_t entry;
  beken_thread_arg_t arg;
};

static FAR void *bk7258_rtos_thread_trampoline(FAR void *arg)
{
  FAR struct bk7258_rtos_thread_s *b = arg;
  FAR beken_thread_function_t entry = b->entry;
  FAR beken_thread_arg_t entry_arg = b->arg;

  kmm_free(b);
  entry(entry_arg);
  return NULL;
}

static bk_err_t bk7258_rtos_thread_spawn(beken_thread_t *thread,
                                         uint8_t priority, const char *name,
                                         beken_thread_function_t function,
                                         uint32_t stack_size,
                                         beken_thread_arg_t arg)
{
  FAR struct bk7258_rtos_thread_s *b;
  pthread_attr_t attr;
  struct sched_param param;
  pthread_t tid;
  int ret;

  b = kmm_malloc(sizeof(*b));
  if (b == NULL)
    {
      return BK_ERR_NO_MEM;
    }

  b->entry = function;
  b->arg = arg;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, stack_size);
  ret = pthread_create(&tid, &attr, bk7258_rtos_thread_trampoline, b);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      kmm_free(b);
      return BK_FAIL;
    }

  param.sched_priority = priority;
  pthread_setschedprio(tid, param.sched_priority);
  pthread_detach(tid);

  if (thread != NULL)
    {
      *thread = (beken_thread_t)(uintptr_t)tid;
    }

  return BK_OK;
}

bk_err_t rtos_create_thread(beken_thread_t *thread, uint8_t priority,
                            const char *name, beken_thread_function_t function,
                            uint32_t stack_size, beken_thread_arg_t arg)
{
  return bk7258_rtos_thread_spawn(thread, priority, name, function,
                                  stack_size, arg);
}

bk_err_t rtos_create_sram_thread(beken_thread_t *thread, uint8_t priority,
                                 const char *name,
                                 beken_thread_function_t function,
                                 uint32_t stack_size, beken_thread_arg_t arg)
{
  return bk7258_rtos_thread_spawn(thread, priority, name, function,
                                  stack_size, arg);
}

bk_err_t rtos_create_psram_thread(beken_thread_t *thread, uint8_t priority,
                                  const char *name,
                                  beken_thread_function_t function,
                                  uint32_t stack_size, beken_thread_arg_t arg)
{
  return bk7258_rtos_thread_spawn(thread, priority, name, function,
                                  stack_size, arg);
}

