/****************************************************************************
 * Semaphore
 ****************************************************************************/

struct bk7258_rtos_sem_s
{
  sem_t sem;
  unsigned int max_count;
  volatile unsigned int count;
};

bk_err_t rtos_init_semaphore(beken_semaphore_t *semaphore, int max_count)
{
  return rtos_init_semaphore_ex(semaphore, max_count, 0);
}

bk_err_t rtos_init_semaphore_ex(beken_semaphore_t *semaphore, int max_count,
                                 int init_count)
{
  FAR struct bk7258_rtos_sem_s *s;

  s = kmm_zalloc(sizeof(*s));
  if (s == NULL)
    {
      return BK_ERR_NO_MEM;
    }

  nxsem_init(&s->sem, 0, init_count > 0 ? init_count : 0);
  nxsem_set_protocol(&s->sem, SEM_PRIO_NONE);
  s->max_count = max_count > 0 ? (unsigned int)max_count : 0;
  s->count = init_count > 0 ? (unsigned int)init_count : 0;

  *semaphore = (beken_semaphore_t)s;
  return BK_OK;
}

bk_err_t rtos_set_semaphore(beken_semaphore_t *semaphore)
{
  FAR struct bk7258_rtos_sem_s *s = (FAR void *)semaphore;
  uint32_t flags;

  if (s->max_count != 0)
    {
      flags = enter_critical_section();
      if (s->count >= s->max_count)
        {
          leave_critical_section(flags);
          return BK_ERR_BUSY;
        }

      s->count++;
      leave_critical_section(flags);
    }

  return nxsem_post(&s->sem) < 0 ? BK_FAIL : BK_OK;
}

bk_err_t rtos_get_semaphore(beken_semaphore_t *semaphore, uint32_t timeout_ms)
{
  FAR struct bk7258_rtos_sem_s *s = (FAR void *)semaphore;
  uint32_t flags;
  int ret;

  if (timeout_ms == BEKEN_NO_WAIT)
    {
      ret = nxsem_trywait(&s->sem);
    }
  else if (timeout_ms == BEKEN_WAIT_FOREVER)
    {
      ret = nxsem_wait(&s->sem);
    }
  else
    {
      ret = nxsem_tickwait(&s->sem, MSEC2TICK(timeout_ms));
    }

  if (ret >= 0)
    {
      flags = enter_critical_section();
      if (s->count > 0)
        {
          s->count--;
        }

      leave_critical_section(flags);
    }

  return ret < 0 ? BK_FAIL : BK_OK;
}

int rtos_get_semaphore_count(beken_semaphore_t *semaphore)
{
  FAR struct bk7258_rtos_sem_s *s = (FAR void *)semaphore;
  int value = 0;

  nxsem_get_value(&s->sem, &value);
  return value;
}

bk_err_t rtos_deinit_semaphore(beken_semaphore_t *semaphore)
{
  FAR struct bk7258_rtos_sem_s *s = (FAR void *)semaphore;

  nxsem_destroy(&s->sem);
  kmm_free(s);
  return BK_OK;
}

/****************************************************************************
 * Mutex
 ****************************************************************************/

bk_err_t rtos_init_mutex(beken_mutex_t *mutex)
{
  FAR mutex_t *m = kmm_malloc(sizeof(*m));
  if (m == NULL)
    {
      return BK_ERR_NO_MEM;
    }

  nxmutex_init(m);
  *mutex = (beken_mutex_t)m;
  return BK_OK;
}

bk_err_t rtos_trylock_mutex(beken_mutex_t *mutex)
{
  return nxmutex_trylock((FAR mutex_t *)mutex) < 0 ? BK_FAIL : BK_OK;
}

bk_err_t rtos_lock_mutex(beken_mutex_t *mutex)
{
  return nxmutex_lock((FAR mutex_t *)mutex) < 0 ? BK_FAIL : BK_OK;
}

bk_err_t rtos_lock_mutex_timeout(beken_mutex_t *mutex, uint32_t timeout_ms)
{
  int i;

  for (i = 0; i < (int)timeout_ms; i++)
    {
      if (nxmutex_trylock((FAR mutex_t *)mutex) == 0)
        {
          return BK_OK;
        }

      nxsig_usleep(1000);
    }

  return BK_ERR_TIMEOUT;
}

bk_err_t rtos_unlock_mutex(beken_mutex_t *mutex)
{
  return nxmutex_unlock((FAR mutex_t *)mutex) < 0 ? BK_FAIL : BK_OK;
}

bk_err_t rtos_deinit_mutex(beken_mutex_t *mutex)
{
  nxmutex_destroy((FAR mutex_t *)mutex);
  kmm_free((FAR void *)mutex);
  return BK_OK;
}

bk_err_t rtos_init_recursive_mutex(beken_mutex_t *mutex)
{
  return rtos_init_mutex(mutex);
}

bk_err_t rtos_lock_recursive_mutex(beken_mutex_t *mutex)
{
  return rtos_lock_mutex(mutex);
}

bk_err_t rtos_unlock_recursive_mutex(beken_mutex_t *mutex)
{
  return rtos_unlock_mutex(mutex);
}

bk_err_t rtos_deinit_recursive_mutex(beken_mutex_t *mutex)
{
  return rtos_deinit_mutex(mutex);
}

