/****************************************************************************
 * Queue
 ****************************************************************************/

static int bk7258_rtos_queue_wait(FAR sem_t *sem, uint32_t timeout_ms)
{
  if (timeout_ms == BEKEN_NO_WAIT)
    {
      return nxsem_trywait(sem);
    }

  if (timeout_ms == BEKEN_WAIT_FOREVER)
    {
      return nxsem_wait(sem);
    }

  return nxsem_tickwait(sem, MSEC2TICK(timeout_ms));
}

struct bk7258_rtos_queue_s
{
  size_t msg_size;
  size_t capacity;
  size_t head;
  size_t tail;
  size_t count;
  sem_t count_sem;
  sem_t space_sem;
  mutex_t lock;
  uint8_t buf[];
};

bk_err_t rtos_init_queue(beken_queue_t *queue, const char *name,
                         uint32_t message_size, uint32_t number_of_messages)
{
  FAR struct bk7258_rtos_queue_s *q;
  size_t alloc;

  alloc = sizeof(*q) + (size_t)message_size * number_of_messages;
  q = kmm_zalloc(alloc);
  if (q == NULL)
    {
      return BK_ERR_NO_MEM;
    }

  q->msg_size = message_size;
  q->capacity = number_of_messages;

  nxsem_init(&q->count_sem, 0, 0);
  nxsem_set_protocol(&q->count_sem, SEM_PRIO_NONE);
  nxsem_init(&q->space_sem, 0, number_of_messages);
  nxsem_set_protocol(&q->space_sem, SEM_PRIO_NONE);
  nxmutex_init(&q->lock);

  *queue = (beken_queue_t)q;
  return BK_OK;
}

bk_err_t rtos_push_to_queue(beken_queue_t *queue, void *message,
                            uint32_t timeout_ms)
{
  FAR struct bk7258_rtos_queue_s *q = (FAR void *)queue;
  int ret;

  ret = bk7258_rtos_queue_wait(&q->space_sem, timeout_ms);
  if (ret < 0)
    {
      return BK_FAIL;
    }

  nxmutex_lock(&q->lock);
  memcpy(&q->buf[q->tail * q->msg_size], message, q->msg_size);
  q->tail = (q->tail + 1) % q->capacity;
  q->count++;
  nxmutex_unlock(&q->lock);

  nxsem_post(&q->count_sem);
  return BK_OK;
}

bk_err_t rtos_push_to_queue_front(beken_queue_t *queue, void *message,
                                  uint32_t timeout_ms)
{
  return rtos_push_to_queue(queue, message, timeout_ms);
}

bk_err_t rtos_pop_from_queue(beken_queue_t *queue, void *message,
                             uint32_t timeout_ms)
{
  FAR struct bk7258_rtos_queue_s *q = (FAR void *)queue;
  int ret;

  ret = bk7258_rtos_queue_wait(&q->count_sem, timeout_ms);
  if (ret < 0)
    {
      return BK_FAIL;
    }

  nxmutex_lock(&q->lock);
  memcpy(message, &q->buf[q->head * q->msg_size], q->msg_size);
  q->head = (q->head + 1) % q->capacity;
  q->count--;
  nxmutex_unlock(&q->lock);

  nxsem_post(&q->space_sem);
  return BK_OK;
}

bk_err_t rtos_deinit_queue(beken_queue_t *queue)
{
  FAR struct bk7258_rtos_queue_s *q = (FAR void *)queue;

  nxsem_destroy(&q->count_sem);
  nxsem_destroy(&q->space_sem);
  kmm_free(q);
  return BK_OK;
}

bool rtos_is_queue_empty(beken_queue_t *queue)
{
  FAR struct bk7258_rtos_queue_s *q = (FAR void *)queue;

  return q->count == 0;
}

bool rtos_is_queue_full(beken_queue_t *queue)
{
  FAR struct bk7258_rtos_queue_s *q = (FAR void *)queue;

  return q->count == q->capacity;
}

bool rtos_reset_queue(beken_queue_t *queue)
{
  FAR struct bk7258_rtos_queue_s *q = (FAR void *)queue;

  nxmutex_lock(&q->lock);
  q->head = 0;
  q->tail = 0;
  q->count = 0;
  nxmutex_unlock(&q->lock);
  return true;
}

/****************************************************************************
 * Event flags
 ****************************************************************************/

struct bk7258_rtos_event_s
{
  sem_t sem;
  volatile uint32_t flags;
};

bk_err_t rtos_init_event_flags(beken_event_t *event_flags)
{
  FAR struct bk7258_rtos_event_s *e = kmm_zalloc(sizeof(*e));
  if (e == NULL)
    {
      return BK_ERR_NO_MEM;
    }

  nxsem_init(&e->sem, 0, 0);
  nxsem_set_protocol(&e->sem, SEM_PRIO_NONE);
  *event_flags = (beken_event_t)e;
  return BK_OK;
}

beken_event_flags_t rtos_wait_for_event_flags(beken_event_t *event_flags,
                                              uint32_t flags_to_wait_for,
                                              uint32_t clear_flags,
                                              uint32_t all_flags,
                                              uint32_t timeout_ms)
{
  FAR struct bk7258_rtos_event_s *e = (FAR void *)event_flags;
  uint32_t flags;
  int ret;

  (void)clear_flags;
  (void)all_flags;

  ret = bk7258_rtos_queue_wait(&e->sem, timeout_ms);
  if (ret < 0)
    {
      return 0;
    }

  flags = e->flags;
  e->flags &= ~flags_to_wait_for;
  return flags;
}

void rtos_set_event_flags(beken_event_t *event_flags, uint32_t flags_to_set)
{
  FAR struct bk7258_rtos_event_s *e = (FAR void *)event_flags;
  uint32_t flags;

  flags = enter_critical_section();
  e->flags |= flags_to_set;
  leave_critical_section(flags);
  nxsem_post(&e->sem);
}

beken_event_flags_t rtos_clear_event_flags(beken_event_t *event_flags,
                                           uint32_t flags_to_clear)
{
  FAR struct bk7258_rtos_event_s *e = (FAR void *)event_flags;
  uint32_t flags;
  uint32_t old;

  flags = enter_critical_section();
  old = e->flags;
  e->flags &= ~flags_to_clear;
  leave_critical_section(flags);
  return old;
}

bk_err_t rtos_deinit_event_flags(beken_event_t *event_flags)
{
  FAR struct bk7258_rtos_event_s *e = (FAR void *)event_flags;

  nxsem_destroy(&e->sem);
  kmm_free(e);
  return BK_OK;
}

