/****************************************************************************
 * Timer
 ****************************************************************************/

struct bk7258_rtos_timer_s
{
  struct wdog_s wdog;
  struct work_s work;
  timer_handler_t cb;
  void *arg;
  uint32_t period_ms;
  bool running;
};

static void bk7258_rtos_timer_wdog(wdparm_t arg)
{
  FAR struct bk7258_rtos_timer_s *t = (FAR void *)arg;

  work_queue(LPWORK, &t->work, bk7258_rtos_timer_work, t, 0);
}

static void bk7258_rtos_timer_work(FAR void *arg)
{
  FAR struct bk7258_rtos_timer_s *t = arg;

  t->cb(t->arg);
  if (t->running)
    {
      wd_start(&t->wdog, MSEC2TICK(t->period_ms),
               bk7258_rtos_timer_wdog, (wdparm_t)t);
    }
}

bk_err_t rtos_init_timer(beken_timer_t *timer, uint32_t time_ms,
                         timer_handler_t function, void *arg)
{
  FAR struct bk7258_rtos_timer_s *t;

  t = kmm_zalloc(sizeof(*t));
  if (t == NULL)
    {
      return BK_ERR_NO_MEM;
    }

  t->cb = function;
  t->arg = arg;
  t->period_ms = time_ms;

  timer->handle = t;
  timer->function = function;
  timer->arg = arg;
  return BK_OK;
}

bk_err_t rtos_start_timer(beken_timer_t *timer)
{
  FAR struct bk7258_rtos_timer_s *t = timer->handle;

  if (t->running)
    {
      return BK_OK;
    }

  t->running = true;
  wd_start(&t->wdog, MSEC2TICK(t->period_ms),
           bk7258_rtos_timer_wdog, (wdparm_t)t);
  return BK_OK;
}

bk_err_t rtos_stop_timer(beken_timer_t *timer)
{
  FAR struct bk7258_rtos_timer_s *t = timer->handle;

  wd_cancel(&t->wdog);
  work_cancel(LPWORK, &t->work);
  t->running = false;
  return BK_OK;
}

bk_err_t rtos_reload_timer(beken_timer_t *timer)
{
  FAR struct bk7258_rtos_timer_s *t = timer->handle;

  wd_cancel(&t->wdog);
  t->running = true;
  wd_start(&t->wdog, MSEC2TICK(t->period_ms),
           bk7258_rtos_timer_wdog, (wdparm_t)t);
  return BK_OK;
}

bk_err_t rtos_deinit_timer(beken_timer_t *timer)
{
  FAR struct bk7258_rtos_timer_s *t = timer->handle;

  wd_cancel(&t->wdog);
  work_cancel(LPWORK, &t->work);
  kmm_free(t);
  timer->handle = NULL;
  return BK_OK;
}

bool rtos_is_timer_init(beken_timer_t *timer)
{
  return timer->handle != NULL;
}

bool rtos_is_timer_running(beken_timer_t *timer)
{
  FAR struct bk7258_rtos_timer_s *t = timer->handle;

  return t != NULL && t->running;
}

bk_err_t rtos_change_period(beken_timer_t *timer, uint32_t time_ms)
{
  FAR struct bk7258_rtos_timer_s *t = timer->handle;

  t->period_ms = time_ms;
  return BK_OK;
}

