/*
 * chips/bk7258/wifi/bk7258_wifi_init.c
 *
 * BK7258 Wi-Fi initialization entry (NuttX side).
 *
 * Owns the single per-device instance and drives the bring-up order:
 * HW glue (clock/power/IRQ) -> board config -> lower-half register. The
 * NuttX scheduler/OS is already running, so there is no OSAL-init step. The
 * vendor MAC/PHY/RF runtime init is added here once the vendored glue and
 * prebuilt libraries are wired (plan §11.4.5 vendored-fork path).
 */

#include <nuttx/config.h>

#include "bk7258_wifi_internal.h"

/****************************************************************************
 * Private data
 ****************************************************************************/

static struct bk7258_wifi_s g_bk7258_wifi;

/****************************************************************************
 * Public entry
 ****************************************************************************/

int bk7258_wifi_initialize(void)
{
  int ret;

  ret = bk7258_wifi_hw_init();
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_wifi_board_init();
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_wifi_lower_init(&g_bk7258_wifi);
  if (ret < 0)
    {
      return ret;
    }

  return bk7258_wifi_lower_register(&g_bk7258_wifi);
}

