/****************************************************************************
 * Event extension (rtos_ext.h)
 ****************************************************************************/

bk_err_t rtos_init_event_ex(rtos_event_ext_t *event_ext)
{
  event_ext->event_flag = 0;
  return rtos_init_semaphore(&event_ext->event_semaphore, 1);
}

bk_err_t deinit_event_ex(rtos_event_ext_t *event_ext)
{
  return rtos_deinit_semaphore(&event_ext->event_semaphore);
}

uint32_t set_event_ex(rtos_event_ext_t *event_ext, uint32_t event)
{
  uint32_t flags;

  flags = enter_critical_section();
  event_ext->event_flag |= event;
  leave_critical_section(flags);

  rtos_set_semaphore(&event_ext->event_semaphore);
  return event_ext->event_flag;
}

uint32_t wait_event_ex(rtos_event_ext_t *event_ext, uint32_t event,
                       uint32_t timeout_ms)
{
  uint32_t flags;
  uint32_t ret;

  rtos_get_semaphore(&event_ext->event_semaphore, timeout_ms);

  flags = enter_critical_section();
  ret = event_ext->event_flag & event;
  event_ext->event_flag &= ~event;
  leave_critical_section(flags);

  return ret;
}

/****************************************************************************
 * High-priority ISR (rtos_ext.h) -> HP work queue
 ****************************************************************************/

struct bk7258_hisr_work_s
{
  struct work_s work;
  rtos_hisr_cb_t cb;
};

static void bk7258_hisr_worker(FAR void *arg)
{
  FAR struct bk7258_hisr_work_s *h = arg;

  h->cb();
  kmm_free(h);
}

void rtos_activate_hisr(rtos_hisr_cb_t isr, int8_t priority)
{
  FAR struct bk7258_hisr_work_s *h;

  (void)priority;
  h = kmm_malloc(sizeof(*h));
  if (h == NULL)
    {
      return;
    }

  h->cb = isr;
  work_queue(HPWORK, &h->work, bk7258_hisr_worker, h, 0);
}

bk_err_t rtos_create_hisr(rtos_hisr_cb_t isr, int8_t priority, char *name)
{
  /* Deferred: the hisr is created lazily on first activate. */
  (void)isr;
