/*
 * chips/bk7258/wifi/glue/include/sys_driver.h
 *
 * NuttX reimplementation of the Armino sys_ctrl driver callbacks the vendored
 * glue registers into the Wi-Fi driver capability table. Only the interrupt
 * and modem-clock subset used by rw_task.c / bk_wifi_adapter.c is declared;
 * implementations are in hw_driver_shim.c and map onto the team chip layer.
 */

#ifndef __BK7258_WIFI_GLUE_SYS_DRIVER_H
#define __BK7258_WIFI_GLUE_SYS_DRIVER_H

#include <stdint.h>
#include <stdbool.h>

#include <common/bk_include.h>
#include <components/log.h>
#include <modules/pm.h>

#ifdef __cplusplus
extern "C" {
#endif

int32_t sys_drv_int_disable(uint32_t param);
int32_t sys_drv_int_enable(uint32_t param);
int32_t sys_drv_int_group2_disable(uint32_t param);
int32_t sys_drv_int_group2_enable(uint32_t param);

uint32_t sys_drv_modem_bus_clk_ctrl(bool clk_en);
uint32_t sys_drv_modem_clk_ctrl(bool clk_en);

int32_t sys_drv_module_power_state_get(power_module_name_t module);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_SYS_DRIVER_H */

/*
 * chips/bk7258/wifi/glue/include/sys_ll.h
 *
 * NuttX reimplementation of the Armino low-level SYS register accessors used
 * by the vendored glue (clock-enable state, OFDM sleep/power). Maps onto the
 * team chip-layer register bits in bk7258_memorymap.h.
 */

#ifndef __BK7258_WIFI_GLUE_SYS_LL_H
#define __BK7258_WIFI_GLUE_SYS_LL_H

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

uint32_t sys_ll_get_cpu_device_clk_enable_mac_cken(void);
uint32_t sys_ll_get_cpu_device_clk_enable_phy_cken(void);

void     sys_ll_set_cpu_power_sleep_wakeup_pwd_ofdm(uint32_t v);
uint32_t sys_ll_get_cpu_power_sleep_wakeup_pwd_ofdm(void);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_SYS_LL_H */

/*
 * chips/bk7258/wifi/glue/include/gpio_driver.h
 *
 * NuttX reimplementation of the Armino GPIO-device mapping used only by the
 * vendor debug-GPIO hook. Skeleton: mapping is a no-op returning OK until the
 * team gpio layer exposes device muxing.
 */

#ifndef __BK7258_WIFI_GLUE_GPIO_DRIVER_H
#define __BK7258_WIFI_GLUE_GPIO_DRIVER_H

#include <stdint.h>

#include <common/bk_err.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef uint32_t gpio_id_t;
typedef uint32_t gpio_dev_t;

#define GPIO_2            2
#define GPIO_3            3
#define GPIO_4            4
#define GPIO_DEV_DEBUG0   0xC0u
#define GPIO_DEV_DEBUG1   0xC1u
#define GPIO_DEV_DEBUG2   0xC2u

bk_err_t gpio_dev_map(gpio_id_t gpio_id, gpio_dev_t dev);
bk_err_t gpio_dev_unmap(gpio_id_t gpio_id);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_GPIO_DRIVER_H */

/*
 * chips/bk7258/wifi/glue/include/driver/ckmn.h
 *
 * NuttX reimplementation of the Armino CKMN (clock manager) driver callbacks
 * used by the vendored glue. Only the RC32k PPM getter the glue calls is
 * declared; it returns 0 (uncalibrated) until the team ckmn driver exists.
 */

#ifndef __BK7258_WIFI_GLUE_DRIVER_CKMN_H
#define __BK7258_WIFI_GLUE_DRIVER_CKMN_H

#include <common/bk_err.h>

#ifdef __cplusplus
extern "C" {
#endif

bk_err_t bk_ckmn_driver_init(void);
bk_err_t bk_ckmn_driver_deinit(void);
bk_err_t bk_ckmn_driver_get_rc32k_ppm(void);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_DRIVER_CKMN_H */

/*
 * chips/bk7258/wifi/glue/include/driver/aon_rtc.h
 *
 * NuttX reimplementation of the Armino AON-RTC driver surface used by the
 * vendored glue. Skeleton: init/deinit are no-op success; period-timer create/
 * destroy return BK_ERR_NOT_SUPPORT until the team aon-rtc driver exists.
 */

#ifndef __BK7258_WIFI_GLUE_DRIVER_AON_RTC_H
#define __BK7258_WIFI_GLUE_DRIVER_AON_RTC_H

#include <stdint.h>
#include <stdbool.h>

#include <common/bk_err.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef uint32_t aon_rtc_id_t;
typedef uint32_t rtc_tick_t;

bk_err_t bk_aon_rtc_driver_init(void);
bk_err_t bk_aon_rtc_driver_deinit(void);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_DRIVER_AON_RTC_H */

/*
 * chips/bk7258/wifi/glue/hw_driver_shim.c
 *
 * NuttX implementation of the Armino sys_ctrl / sys_ll / gpio / ckmn / aon-rtc
 * callbacks the vendored glue registers into the Wi-Fi driver capability
 * table. Interrupt-enable and modem-clock callbacks map onto the team chip
 * layer register bits (bk7258_memorymap.h); power/OFDM/RC32k/GPIO remain
 * skeleton no-ops until the corresponding team drivers exist.
 */

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <stdint.h>
#include <stdbool.h>

#include <bk7258_memorymap.h>

#include "sys_driver.h"
#include "sys_ll.h"
#include "gpio_driver.h"
#include "driver/ckmn.h"
#include "driver/aon_rtc.h"

/****************************************************************************
 * Interrupt enable (SYS_CPU0_INT_EN / INT_EN_HI)
 ****************************************************************************/

int32_t sys_drv_int_enable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN, param, param);
  return 0;
}

int32_t sys_drv_int_disable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN, param, 0);
  return 0;
}

int32_t sys_drv_int_group2_enable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI, param, param);
  return 0;
}

int32_t sys_drv_int_group2_disable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI, param, 0);
  return 0;
}

/****************************************************************************
 * Modem / MAC / PHY clock (SYS_DEV_CLK_EN)
 ****************************************************************************/

uint32_t sys_drv_modem_bus_clk_ctrl(bool clk_en)
{
  uint32_t v = clk_en ? BK7258_SYS_MAC_CKEN : 0;

  modifyreg32(BK7258_SYS_DEV_CLK_EN, BK7258_SYS_MAC_CKEN, v);
  return 0;
}

uint32_t sys_drv_modem_clk_ctrl(bool clk_en)
{
  uint32_t v = clk_en ? BK7258_SYS_PHY_CKEN : 0;

  modifyreg32(BK7258_SYS_DEV_CLK_EN, BK7258_SYS_PHY_CKEN, v);
  return 0;
}

/****************************************************************************
 * sys_ll clock-enable state
 ****************************************************************************/

uint32_t sys_ll_get_cpu_device_clk_enable_mac_cken(void)
{
  return (getreg32(BK7258_SYS_DEV_CLK_EN) & BK7258_SYS_MAC_CKEN) ? 1 : 0;
}

uint32_t sys_ll_get_cpu_device_clk_enable_phy_cken(void)
{
  return (getreg32(BK7258_SYS_DEV_CLK_EN) & BK7258_SYS_PHY_CKEN) ? 1 : 0;
}

/****************************************************************************
 * Module power state (skeleton)
 ****************************************************************************/

int32_t sys_drv_module_power_state_get(power_module_name_t module)
{
  (void)module;
  return PM_POWER_MODULE_STATE_ON;
}

/****************************************************************************
 * OFDM sleep/wakeup power (skeleton — register not yet pinned)
 ****************************************************************************/

static uint32_t g_bk7258_ofdm_pwd;

void sys_ll_set_cpu_power_sleep_wakeup_pwd_ofdm(uint32_t v)
{
  g_bk7258_ofdm_pwd = v;
}

uint32_t sys_ll_get_cpu_power_sleep_wakeup_pwd_ofdm(void)
{
  return g_bk7258_ofdm_pwd;
}

/****************************************************************************
 * GPIO device mapping (skeleton no-op)
 ****************************************************************************/

bk_err_t gpio_dev_map(gpio_id_t gpio_id, gpio_dev_t dev)
{
  (void)gpio_id;
  (void)dev;
  return BK_OK;
}

bk_err_t gpio_dev_unmap(gpio_id_t gpio_id)
{
  (void)gpio_id;
  return BK_OK;
}

/****************************************************************************
 * CKMN (skeleton)
 ****************************************************************************/

bk_err_t bk_ckmn_driver_init(void)
{
  return BK_OK;
}

bk_err_t bk_ckmn_driver_deinit(void)
{
  return BK_OK;
}

bk_err_t bk_ckmn_driver_get_rc32k_ppm(void)
{
  return 0;
}

/****************************************************************************
 * AON RTC (skeleton)
 ****************************************************************************/

bk_err_t bk_aon_rtc_driver_init(void)
{
  return BK_OK;
}

bk_err_t bk_aon_rtc_driver_deinit(void)
{
  return BK_OK;
}

