/*
 * chips/bk7258/wifi/glue/netif_shim.c
 *
 * NuttX adaptation of the Armino bk_netif_* API. get_ip4_config reads the
 * NuttX netdev address back into the string form the glue expects; the
 * lwIP-only operations (static IP set, dhcpc start, IP6 info) return
 * documented errors until wired to NuttX dhcpc / SIOCSIFADDR.
 */

#include <nuttx/config.h>
#include <nuttx/net/netdev.h>
#include <nuttx/net/ip.h>

#include <netinet/in.h>
#include <arpa/inet.h>

#include <string.h>

#include "components/netif.h"

bk_err_t bk_netif_init(void)
{
  return BK_OK;
}

bk_err_t bk_netif_get_ip4_config(netif_if_t ifx, netif_ip4_config_t *config)
{
  FAR struct net_driver_s *dev;
  FAR const char *ifname;

  if (config == NULL)
    {
      return BK_ERR_NULL_PARAM;
    }

  ifname = (ifx == NETIF_IF_STA) ? "wlan0" : "wlan1";
  dev = netdev_findbyname(ifname);
  if (dev == NULL)
    {
      return BK_ERR_NO_DEV;
    }

  if (dev->d_ipaddr == 0)
    {
      config->ip[0] = '\0';
      config->mask[0] = '\0';
      config->gateway[0] = '\0';
      config->dns[0] = '\0';
    }
  else
    {
      inet_ntop(AF_INET, &dev->d_ipaddr, config->ip, NETIF_IP4_STR_LEN);
      inet_ntop(AF_INET, &dev->d_netmask, config->mask, NETIF_IP4_STR_LEN);
      inet_ntop(AF_INET, &dev->d_draddr, config->gateway, NETIF_IP4_STR_LEN);
      config->dns[0] = '\0';
    }

  return BK_OK;
}

bk_err_t bk_netif_set_ip4_config(netif_if_t ifx, const netif_ip4_config_t *config)
{
  /* lwIP static-IP path is dropped; NuttX owns interface addressing. */
  (void)ifx;
  (void)config;
  return BK_ERR_NOT_SUPPORT;
}

bk_err_t bk_netif_get_ip6_addr_info(netif_if_t ifx)
{
  (void)ifx;
  return BK_FAIL;
}

bk_err_t bk_netif_dhcpc_start(netif_if_t ifx)
{
  /* NuttX dhcpc is started by the application layer; not a vendor callback. */
  (void)ifx;
  return BK_ERR_NOT_SUPPORT;
}

bk_err_t bk_netif_static_ip(netif_ip4_config_t static_ip4_config)
{
  (void)static_ip4_config;
  return BK_ERR_NOT_SUPPORT;
}

