/*
 * chips/bk7258/wifi/glue/pbuf_shim.c
 *
 * NuttX implementation of the vendor packet ABI declared in
 * glue/include/lwip/pbuf.h. lwIP itself is not compiled -- only the pbuf
 * layout is reused, because the vendored glue reads its fields directly and
 * places its private descriptor at `(uint8_t *)p + sizeof(struct pbuf)`
 * (rwnx_tx.c:581).
 *
 * Backed by the NuttX kernel heap. Allocation is one contiguous block:
 *
 *   +----------------+-------------------+---------------------+
 *   | struct pbuf    | headroom (layer)  | payload (length)    |
 *   +----------------+-------------------+---------------------+
 *   ^ p              ^ p + sizeof(*p)    ^ p->payload
 *                      = sk_buff / tx descriptor
 *
 * No padding is inserted between the struct and the headroom: the glue
 * computes its descriptor address from sizeof(struct pbuf), so that boundary
 * must be exact.
 */

#include <nuttx/config.h>
#include <nuttx/kmalloc.h>

#include <assert.h>
#include <stdint.h>
#include <string.h>

#include "lwip/pbuf.h"

/****************************************************************************
 * Pre-processor definitions
 ****************************************************************************/

#define PBUF_SHIM_ALIGN       4
#define PBUF_SHIM_ALIGN_UP(x) (((x) + (PBUF_SHIM_ALIGN - 1)) & \
                               ~((size_t)PBUF_SHIM_ALIGN - 1))

/* The descriptor the glue expects at p + sizeof(struct pbuf) must stay
 * naturally aligned, so the layout itself has to be a multiple of 4.
 */

static_assert(sizeof(struct pbuf) % PBUF_SHIM_ALIGN == 0,
              "struct pbuf size must stay 4-byte aligned");

/****************************************************************************
 * Private functions
 ****************************************************************************/

static inline uint8_t *pbuf_shim_base(FAR struct pbuf *p)
{
  return (FAR uint8_t *)p + sizeof(struct pbuf);
}

/****************************************************************************
 * Public functions
 ****************************************************************************/

FAR struct pbuf *pbuf_alloc(pbuf_layer layer, u16_t length, pbuf_type type)
{
  FAR struct pbuf *p;
  size_t offset = (size_t)layer;

  p = kmm_malloc(sizeof(struct pbuf) + offset +
                 PBUF_SHIM_ALIGN_UP((size_t)length));
  if (p == NULL)
    {
      return NULL;
    }

  p->next          = NULL;
  p->payload       = pbuf_shim_base(p) + offset;
  p->tot_len       = length;
  p->len           = length;
  p->type_internal = (u8_t)type;
  p->flags         = 0;
  p->ref           = 1;
  p->if_idx        = 0;

  return p;
}

void pbuf_ref(FAR struct pbuf *p)
{
  if (p != NULL)
    {
      p->ref++;
    }
}

u8_t pbuf_free(FAR struct pbuf *p)
{
  u8_t count = 0;

  while (p != NULL)
    {
      FAR struct pbuf *next;

      if (p->ref > 0)
        {
          p->ref--;
        }

      if (p->ref != 0)
        {
          break;
        }

      next = p->next;
      kmm_free(p);
      count++;
      p = next;
    }

  return count;
}

u8_t pbuf_header(FAR struct pbuf *p, s16_t header_size)
{
  FAR uint8_t *payload;

  if (p == NULL)
    {
      return 1;
    }

  if (header_size == 0)
    {
      return 0;
    }

  if (header_size > 0)
    {
      /* Growing the header: the payload moves back, and must not cross into
       * the struct itself.
       */

      payload = (FAR uint8_t *)p->payload - header_size;
      if (payload < pbuf_shim_base(p))
        {
          return 1;
        }
    }
  else
    {
      /* Shrinking: reject before the subtraction underflows. The int32_t cast
       * keeps the negation safe for header_size == INT16_MIN.
       */

      uint32_t shrink = (uint32_t)(-(int32_t)header_size);

      if (shrink > p->len)
        {
          return 1;
        }

      payload = (FAR uint8_t *)p->payload + shrink;
    }

  p->payload = payload;
  p->len     = (u16_t)(p->len + header_size);
  p->tot_len = (u16_t)(p->tot_len + header_size);

  return 0;
}

void pbuf_cat(FAR struct pbuf *head, FAR struct pbuf *tail)
{
  FAR struct pbuf *p;

  if (head == NULL || tail == NULL)
    {
      return;
    }

  for (p = head; p->next != NULL; p = p->next)
    {
      p->tot_len = (u16_t)(p->tot_len + tail->tot_len);
    }

  p->tot_len = (u16_t)(p->tot_len + tail->tot_len);
  p->next    = tail;
}

err_t pbuf_copy(FAR struct pbuf *p_to, FAR const struct pbuf *p_from)
{
  size_t offset_to = 0;
  size_t offset_from = 0;

  if (p_to == NULL || p_from == NULL)
    {
      return ERR_ARG;
    }

  if (p_to->tot_len < p_from->tot_len)
    {
      return ERR_ARG;
    }

  while (p_from != NULL && p_to != NULL)
    {
      size_t len = (size_t)p_to->len - offset_to;
      size_t avail = (size_t)p_from->len - offset_from;

      if (avail < len)
        {
          len = avail;
        }

      memcpy((FAR uint8_t *)p_to->payload + offset_to,
             (FAR const uint8_t *)p_from->payload + offset_from, len);

      offset_to += len;
      offset_from += len;

      if (offset_from == p_from->len)
        {
          offset_from = 0;
          p_from = p_from->next;
        }

      if (offset_to == p_to->len)
        {
          offset_to = 0;
          p_to = p_to->next;
        }
    }

  return ERR_OK;
}

FAR struct pbuf *pbuf_coalesce(FAR struct pbuf *p, pbuf_layer layer)
{
  FAR struct pbuf *q;

  if (p == NULL || p->next == NULL)
    {
      return p;
    }

  q = pbuf_alloc(layer, p->tot_len, PBUF_RAM);
  if (q == NULL)
    {
      return p;
    }

  if (pbuf_copy(q, p) != ERR_OK)
    {
      pbuf_free(q);
      return p;
    }

  pbuf_free(p);
  return q;
}

